"use client";

import { useFileDrop, useSpreadsheetImport } from "@spotable/spreadsheet-import-react";
import { FileSpreadsheetIcon, UploadCloudIcon } from "lucide-react";
import { Badge, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/spreadsheet-import-primitives";
import { cn } from "@/lib/utils";

export type UploadStepProps = {
  accept?: string;
  /** Hide the "expected columns" preview when the surrounding page already explains it. */
  showTemplate?: boolean;
};

export function UploadStep<TKey extends string>({
  accept = ".csv,.tsv,.xlsx,.xls,.ods",
  showTemplate = true,
}: UploadStepProps) {
  const { getRootProps, getInputProps, isDragging, isBusy } = useFileDrop<TKey>({ accept });
  const { fields } = useSpreadsheetImport<TKey>();

  return (
    <div className="space-y-6">
      <div
        {...getRootProps({
          className: cn(
            "flex cursor-pointer flex-col items-center justify-center gap-3 rounded-lg border-2 border-dashed p-10 text-center transition-colors",
            "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
            isDragging ? "border-primary bg-accent" : "border-input hover:bg-accent/50",
            isBusy && "pointer-events-none opacity-60",
          ),
        })}
      >
        <input {...getInputProps()} />
        <UploadCloudIcon className="size-8 text-muted-foreground" aria-hidden />
        <div className="space-y-1">
          <p className="text-sm font-medium">{isBusy ? "Reading file…" : "Drop a file here, or click to browse"}</p>
          <p className="text-xs text-muted-foreground">{accept.split(",").join(" · ")}</p>
        </div>
      </div>

      {showTemplate ? (
        <section className="space-y-2">
          <div className="flex items-center gap-2">
            <FileSpreadsheetIcon className="size-4 text-muted-foreground" aria-hidden />
            <h3 className="text-sm font-medium">Expected columns</h3>
          </div>
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  {fields.map(field => (
                    <TableHead key={field.key} className="whitespace-nowrap">
                      <span className="inline-flex items-center gap-1.5">
                        {field.label}
                        {field.validations?.some(validation => validation.rule === "required") ? (
                          <Badge variant="secondary" className="px-1 py-0 text-[10px] font-normal">
                            required
                          </Badge>
                        ) : null}
                      </span>
                    </TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                <TableRow>
                  {fields.map(field => (
                    <TableCell key={field.key} className="whitespace-nowrap text-muted-foreground">
                      {field.example ?? "—"}
                    </TableCell>
                  ))}
                </TableRow>
              </TableBody>
            </Table>
          </div>
        </section>
      ) : null}
    </div>
  );
}

"use client";

import { useHeaderSelection, useSheetSelection } from "@spotable/spreadsheet-import-react";
import { Badge, Table, TableBody, TableCell, TableRow } from "@/components/ui/spreadsheet-import-primitives";
import { cn } from "@/lib/utils";

export function SelectSheetStep<TKey extends string>() {
  const { sheets, selected, setSelected, getSheetProps } = useSheetSelection<TKey>();

  return (
    <div role="radiogroup" aria-label="Sheets" className="grid gap-2">
      {sheets.map(sheet => {
        const props = getSheetProps(sheet.name);
        return (
          <button
            key={sheet.name}
            type="button"
            {...props}
            onClick={() => setSelected(sheet.name)}
            className={cn(
              "flex items-center justify-between rounded-md border px-3 py-2 text-left text-sm transition-colors",
              "focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
              selected === sheet.name ? "border-primary bg-accent" : "hover:bg-accent/50",
            )}
          >
            <span className="font-medium">{sheet.name}</span>
            <Badge variant="secondary">{sheet.rowCount} rows</Badge>
          </button>
        );
      })}
    </div>
  );
}

export function SelectHeaderStep<TKey extends string>({ previewRows = 25 }: { previewRows?: number }) {
  const { rows, selectedIndex, getRowProps } = useHeaderSelection<TKey>();
  const width = Math.max(0, ...rows.slice(0, previewRows).map(row => row.length));

  return (
    <div className="rounded-md border">
      <Table>
        <TableBody role="radiogroup" aria-label="Header row">
          {rows.slice(0, previewRows).map((row, index) => (
            <TableRow
              // biome-ignore lint/suspicious/noArrayIndexKey: sheet rows have no identity beyond their position
              key={index}
              {...getRowProps(index)}
              data-state={selectedIndex === index ? "selected" : undefined}
              className={cn("cursor-pointer", selectedIndex === index && "font-medium")}
            >
              <TableCell className="w-10 text-xs text-muted-foreground">{index + 1}</TableCell>
              {Array.from({ length: width }, (_, column) => (
                // biome-ignore lint/suspicious/noArrayIndexKey: cells are positional
                <TableCell key={column} className="max-w-48 truncate">
                  {row[column] ?? ""}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

"use client";

import { type Column, ColumnType, type Field, isMatchedColumn } from "@spotable/spreadsheet-import-core";
import { useColumnMatching } from "@spotable/spreadsheet-import-react";
import { AlertTriangleIcon, EyeIcon, EyeOffIcon } from "lucide-react";
import { useId } from "react";
import { Button } from "@/components/ui/button";
import {
  Alert,
  AlertDescription,
  AlertTitle,
  Badge,
  Card,
  CardContent,
  Input,
  Label,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/spreadsheet-import-primitives";
import { cn } from "@/lib/utils";

/** Radix Select has no empty-string value, so "not imported" needs a sentinel. */
const NONE = "__none__";

type ColumnCardProps<TKey extends string> = {
  column: Column<TKey>;
  fields: readonly Field<TKey>[];
  sample: (string | undefined)[];
  taken: ReadonlySet<TKey>;
  onField: (index: number, key: TKey | null) => void;
  onIgnore: (index: number) => void;
  onUnignore: (index: number) => void;
  onOption: (index: number, entry: string, value: string) => void;
  optionsFor: (key: TKey) => readonly { label: string; value: string }[];
  note?: string | undefined;
};

function ColumnCard<TKey extends string>({
  column,
  fields,
  sample,
  taken,
  onField,
  onIgnore,
  onUnignore,
  onOption,
  optionsFor,
  note,
}: ColumnCardProps<TKey>) {
  const selectId = useId();
  const ignored = column.type === ColumnType.ignored;
  const value = isMatchedColumn(column) ? column.value : NONE;
  const unresolved = "matchedOptions" in column ? column.matchedOptions.filter(option => !option.value).length : 0;

  return (
    <Card className={cn(ignored && "opacity-60")}>
      <CardContent className="grid gap-4 p-4 md:grid-cols-2">
        <div className="min-w-0 space-y-1">
          <p className="truncate text-sm font-medium">{column.header || <em>no header</em>}</p>
          <ul className="space-y-0.5 text-xs text-muted-foreground">
            {sample.map((cell, index) => (
              // biome-ignore lint/suspicious/noArrayIndexKey: sample cells are positional and may repeat
              <li key={index} className="truncate">
                {cell || <em>empty</em>}
              </li>
            ))}
          </ul>
        </div>

        <div className="space-y-3">
          <div className="space-y-1.5">
            <Label htmlFor={selectId} className="sr-only">
              Field for column {column.header}
            </Label>
            <Select
              value={value}
              disabled={ignored}
              onValueChange={next => onField(column.index, next === NONE ? null : (next as TKey))}
            >
              <SelectTrigger id={selectId} aria-label={`Field for column ${column.header}`}>
                <SelectValue placeholder="Not imported" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value={NONE}>Not imported</SelectItem>
                {fields.map(field => (
                  <SelectItem key={field.key} value={field.key} disabled={taken.has(field.key) && field.key !== value}>
                    {field.label}
                    {taken.has(field.key) && field.key !== value ? " (already mapped)" : ""}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {note ? (
            <p className="rounded-md bg-muted/50 px-2 py-1 font-mono text-xs text-muted-foreground">{note}</p>
          ) : null}

          {"matchedOptions" in column ? (
            <div className="space-y-2 rounded-md bg-muted/50 p-2">
              <p className="flex items-center justify-between text-xs font-medium">
                Match the values
                {unresolved > 0 ? (
                  <Badge variant="secondary" className="font-normal">
                    {unresolved} left
                  </Badge>
                ) : null}
              </p>
              {column.matchedOptions.map(option => (
                <div key={option.entry} className="flex items-center gap-2">
                  <span className="w-1/2 truncate text-xs">{option.entry}</span>
                  <Select value={option.value ?? ""} onValueChange={next => onOption(column.index, option.entry, next)}>
                    <SelectTrigger
                      aria-label={`Option for ${option.entry}`}
                      className={cn("h-8 w-1/2 text-xs", !option.value && "border-amber-500")}
                    >
                      <SelectValue placeholder="Pick one" />
                    </SelectTrigger>
                    <SelectContent>
                      {optionsFor(column.value).map(choice => (
                        <SelectItem key={choice.value} value={choice.value}>
                          {choice.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              ))}
            </div>
          ) : null}

          <Button
            variant="ghost"
            size="sm"
            onClick={() => (ignored ? onUnignore(column.index) : onIgnore(column.index))}
          >
            {ignored ? <EyeIcon /> : <EyeOffIcon />}
            {ignored ? "Include" : "Ignore"}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

export function MatchColumnsStep<TKey extends string>() {
  const matching = useColumnMatching<TKey>();

  return (
    <div className="space-y-4">
      {matching.unmatchedRequiredFields.length > 0 ? (
        <Alert variant="warning">
          <AlertTriangleIcon className="size-4" />
          <AlertTitle>Some required columns are not mapped</AlertTitle>
          <AlertDescription>
            {matching.unmatchedRequiredFields.join(", ")}. You can continue, but those values will be empty.
          </AlertDescription>
        </Alert>
      ) : null}

      {matching.unmappedFields.length > 0 ? (
        <Card>
          <CardContent className="space-y-3 p-4">
            <div className="space-y-1">
              <p className="text-sm font-medium">Niet in het bestand</p>
              <p className="text-xs text-muted-foreground">
                Geen kolom levert deze velden. Vul een waarde in en die geldt voor de hele import.
              </p>
            </div>

            <div className="grid gap-2 sm:grid-cols-2">
              {matching.unmappedFields.map(field => {
                const options = field.fieldType.type === "select" ? field.fieldType.options : null;
                const current = matching.constants[field.key];

                return (
                  <div key={field.key} className="flex items-center justify-between gap-2 text-sm">
                    <span className="truncate">{field.label}</span>
                    {options ? (
                      <Select
                        value={String(current ?? NONE)}
                        onValueChange={next => matching.setFieldConstant(field.key, next === NONE ? undefined : next)}
                      >
                        <SelectTrigger aria-label={`Waarde voor ${field.label}`} className="h-8 w-1/2 text-xs">
                          <SelectValue placeholder="Leeg laten" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value={NONE}>Leeg laten</SelectItem>
                          {options.map(option => (
                            <SelectItem key={option.value} value={option.value}>
                              {option.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <Input
                        aria-label={`Waarde voor ${field.label}`}
                        className="h-8 w-1/2 text-xs"
                        placeholder="Leeg laten"
                        defaultValue={String(current ?? "")}
                        onBlur={event => matching.setFieldConstant(field.key, event.target.value || undefined)}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>
      ) : null}

      <div className="grid gap-3">
        {matching.columns.map(column => (
          <ColumnCard
            key={column.index}
            column={column}
            fields={matching.fields}
            sample={matching.getSample(column.index)}
            taken={matching.takenFieldKeys}
            onField={matching.setColumnField}
            onIgnore={matching.ignoreColumn}
            onUnignore={matching.unignoreColumn}
            onOption={matching.setColumnOption}
            optionsFor={matching.getOptionsFor}
            note={matching.getColumnNote(column)}
          />
        ))}
      </div>
    </div>
  );
}

"use client";

import type { CellError, CellValue, Fields, ValidatedRow } from "@spotable/spreadsheet-import-core";
import { useCellDraft, useValidation } from "@spotable/spreadsheet-import-react";
import { memo, type ReactElement } from "react";
import { Button } from "@/components/ui/button";
import {
  Badge,
  Checkbox,
  Input,
  Label,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/spreadsheet-import-primitives";
import { cn } from "@/lib/utils";

/**
 * A text cell that commits on blur or Enter rather than per keystroke. The
 * editing behaviour lives in `useCellDraft`; this is only its styling.
 */
function EditableCell({
  value,
  error,
  label,
  onCommit,
  numeric = false,
  monospace = false,
}: {
  value: CellValue;
  error: CellError | null;
  label: string;
  onCommit: (next: string) => void;
  numeric?: boolean;
  monospace?: boolean;
}) {
  const { getInputProps } = useCellDraft({ value, onCommit });

  return (
    <Input
      {...getInputProps({
        "aria-label": label,
        "aria-invalid": error?.level === "error" || undefined,
        title: error?.message,
        inputMode: numeric ? "decimal" : undefined,
        className: cn(
          "h-8 border-transparent bg-transparent shadow-none hover:border-input",
          numeric && "text-right tabular-nums",
          monospace && "tabular-nums",
          error?.level === "error" && "border-destructive bg-destructive/5",
          error && error.level !== "error" && "border-amber-500 bg-amber-500/5",
        ),
      })}
    />
  );
}

type ValidationRowProps<TKey extends string> = {
  row: ValidatedRow<TKey>;
  fields: Fields<TKey>;
  selected: boolean;
  onToggle: (rowId: string) => void;
  onCellChange: (rowId: string, fieldKey: TKey, value: CellValue) => Promise<void>;
};

/**
 * Memoized so an edit re-renders only the rows it touched: the engine hands
 * back the same row object when nothing about a row changed, and every other
 * prop here is stable.
 */
const ValidationRow = memo(function ValidationRow<TKey extends string>({
  row,
  fields,
  selected,
  onToggle,
  onCellChange,
}: ValidationRowProps<TKey>) {
  return (
    <TableRow data-state={selected ? "selected" : undefined}>
      <TableCell>
        <Checkbox aria-label="Select row" checked={selected} onCheckedChange={() => onToggle(row.__index)} />
      </TableCell>
      {fields.map(field => {
        const value = row[field.key];

        return (
          <TableCell key={field.key} className="min-w-32">
            {field.fieldType.type === "checkbox" ? (
              <Checkbox
                aria-label={field.label}
                checked={value === true}
                onCheckedChange={checked => void onCellChange(row.__index, field.key, checked === true)}
              />
            ) : (
              <EditableCell
                label={field.label}
                value={value ?? ""}
                error={row.__errors?.[field.key] ?? null}
                numeric={field.fieldType.type === "number"}
                monospace={field.fieldType.type === "date"}
                onCommit={next => void onCellChange(row.__index, field.key, next)}
              />
            )}
          </TableCell>
        );
      })}
    </TableRow>
  );
}) as <TKey extends string>(props: ValidationRowProps<TKey>) => ReactElement;

export function ValidationStep<TKey extends string>() {
  const validation = useValidation<TKey>();

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Badge variant="secondary">{validation.validCount} ready</Badge>
          {validation.errorCount > 0 ? (
            <Badge variant="destructive">{validation.errorCount} with problems</Badge>
          ) : null}
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Checkbox
              id="errors-only"
              checked={validation.showErrorsOnly}
              onCheckedChange={checked => validation.setShowErrorsOnly(checked === true)}
            />
            <Label htmlFor="errors-only" className="text-sm font-normal text-muted-foreground">
              Only show problems
            </Label>
          </div>
          {validation.selectedIds.size > 0 ? (
            <Button variant="destructive" size="sm" onClick={() => void validation.deleteSelected()}>
              Delete {validation.selectedIds.size}
            </Button>
          ) : null}
        </div>
      </div>

      <div className="rounded-md border">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-10" />
              {validation.fields.map(field => (
                <TableHead key={field.key} className="whitespace-nowrap">
                  {field.label}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {validation.visibleRows.map(row => (
              <ValidationRow
                key={row.__index}
                row={row}
                fields={validation.fields}
                selected={validation.selectedIds.has(row.__index)}
                onToggle={validation.toggleSelected}
                onCellChange={validation.updateCell}
              />
            ))}
          </TableBody>
        </Table>
      </div>

      <Button variant="outline" size="sm" onClick={() => void validation.addRow()}>
        Add empty row
      </Button>
    </div>
  );
}

"use client";

import { type ImporterOptions, Step } from "@spotable/spreadsheet-import-core";
import { SpreadsheetImportProvider, useSpreadsheetImport } from "@spotable/spreadsheet-import-react";
import { AlertCircleIcon, CheckIcon } from "lucide-react";
import { MatchColumnsStep } from "@/components/spreadsheet-import/match";
import { SelectHeaderStep, SelectSheetStep } from "@/components/spreadsheet-import/select";
import { UploadStep } from "@/components/spreadsheet-import/upload";
import { ValidationStep } from "@/components/spreadsheet-import/validate";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/spreadsheet-import-primitives";
import { cn } from "@/lib/utils";

const STEPS: { step: Step; label: string }[] = [
  { step: Step.upload, label: "Upload" },
  { step: Step.selectHeader, label: "Header" },
  { step: Step.matchColumns, label: "Match" },
  { step: Step.validate, label: "Review" },
];

export function Stepper<TKey extends string>({ className }: { className?: string }) {
  const { step, goToStep } = useSpreadsheetImport<TKey>();
  // Sheet selection is conditional, so it shares the upload dot instead of
  // making the stepper change length mid-flow.
  const currentIndex = Math.max(
    0,
    STEPS.findIndex(entry => entry.step === (step === Step.selectSheet ? Step.upload : step)),
  );

  return (
    <ol className={cn("flex flex-wrap items-center gap-1", className)} aria-label="Import progress">
      {STEPS.map((entry, index) => {
        const state = index < currentIndex ? "done" : index === currentIndex ? "current" : "todo";

        return (
          <li key={entry.step} className="flex items-center gap-1">
            <Button
              variant={state === "current" ? "secondary" : "ghost"}
              size="sm"
              disabled={state === "todo"}
              aria-current={state === "current" ? "step" : undefined}
              onClick={() => goToStep(entry.step)}
              className={cn(state === "todo" && "text-muted-foreground")}
            >
              <span
                className={cn(
                  "grid size-4 place-items-center rounded-full border text-[10px]",
                  state === "done" && "border-primary bg-primary text-primary-foreground",
                )}
              >
                {state === "done" ? <CheckIcon className="size-2.5" /> : index + 1}
              </span>
              {entry.label}
            </Button>
            {index < STEPS.length - 1 ? <span className="h-px w-3 bg-border" aria-hidden /> : null}
          </li>
        );
      })}
    </ol>
  );
}

const COPY: Record<Step, { title: string; description: string }> = {
  [Step.upload]: { title: "Upload a file", description: "CSV, TSV or Excel." },
  [Step.selectSheet]: { title: "Which sheet?", description: "This workbook has more than one." },
  [Step.selectHeader]: { title: "Which row holds the column names?", description: "Rows above it are ignored." },
  [Step.matchColumns]: { title: "Match your columns", description: "We guessed where we could." },
  [Step.validate]: { title: "Review and fix", description: "Edit any cell, or delete rows you do not want." },
  [Step.submitted]: { title: "Imported", description: "" },
};

function StepBody<TKey extends string>({ accept }: { accept?: string }) {
  const { step } = useSpreadsheetImport<TKey>();

  switch (step) {
    case Step.upload:
      return <UploadStep<TKey> {...(accept ? { accept } : {})} />;
    case Step.selectSheet:
      return <SelectSheetStep<TKey> />;
    case Step.selectHeader:
      return <SelectHeaderStep<TKey> />;
    case Step.matchColumns:
      return <MatchColumnsStep<TKey> />;
    case Step.validate:
      return <ValidationStep<TKey> />;
    default:
      return null;
  }
}

function Footer<TKey extends string>({ onDone }: { onDone?: () => void }) {
  const { step, isBusy, back, reset, importer, commitColumns, selectHeaderRow, selectSheet, submit } =
    useSpreadsheetImport<TKey>();

  if (step === Step.upload) return null;

  if (step === Step.submitted) {
    return (
      <div className="flex justify-end gap-2">
        <Button variant="outline" onClick={reset}>
          Import another file
        </Button>
        {onDone ? <Button onClick={onDone}>Done</Button> : null}
      </div>
    );
  }

  const advance = () => {
    if (step === Step.selectSheet) {
      // The sheet step keeps its own selection in `useSheetSelection`, so the
      // footer falls back to the first sheet when nothing was clicked.
      const state = importer.getState();
      const name = state.pendingSheetName ?? state.workbook?.sheets[0]?.name;
      if (name) void selectSheet(name);
    } else if (step === Step.selectHeader) {
      void selectHeaderRow(importer.getState().headerRowIndex);
    } else if (step === Step.matchColumns) {
      void commitColumns();
    } else {
      void submit();
    }
  };

  return (
    <div className="flex items-center justify-between gap-2">
      <Button variant="outline" onClick={back} disabled={isBusy}>
        Back
      </Button>
      <Button onClick={advance} disabled={isBusy}>
        {isBusy ? "Working…" : step === Step.validate ? "Import" : "Continue"}
      </Button>
    </div>
  );
}

function ErrorBanner<TKey extends string>() {
  const { error, clearError } = useSpreadsheetImport<TKey>();
  if (!error) return null;

  return (
    <Alert variant="destructive">
      <AlertCircleIcon className="size-4" />
      <AlertTitle>Could not continue</AlertTitle>
      <AlertDescription className="flex items-center justify-between gap-3">
        <span>{error.message}</span>
        <Button variant="ghost" size="sm" onClick={clearError}>
          Dismiss
        </Button>
      </AlertDescription>
    </Alert>
  );
}

function Flow<TKey extends string>({ accept, onDone }: { accept?: string; onDone?: () => void }) {
  const { step } = useSpreadsheetImport<TKey>();
  const copy = COPY[step];

  return (
    <div className="flex min-h-0 flex-col gap-4">
      <Stepper<TKey> />
      <div className="space-y-1">
        <h2 className="text-base font-semibold">{copy.title}</h2>
        {copy.description ? <p className="text-sm text-muted-foreground">{copy.description}</p> : null}
      </div>
      <ErrorBanner<TKey> />
      <div className="min-h-0 flex-1 overflow-auto">
        <StepBody<TKey> {...(accept ? { accept } : {})} />
      </div>
      <Footer<TKey> {...(onDone ? { onDone } : {})} />
    </div>
  );
}

export type SpreadsheetImportProps<TKey extends string> = ImporterOptions<TKey> & {
  accept?: string;
  className?: string;
};

/** The flow rendered inline, for a dedicated import page. */
export function SpreadsheetImport<TKey extends string>({
  accept,
  className,
  ...options
}: SpreadsheetImportProps<TKey>) {
  return (
    <SpreadsheetImportProvider options={options}>
      <div className={cn("flex min-h-0 flex-col", className)}>
        <Flow<TKey> {...(accept ? { accept } : {})} />
      </div>
    </SpreadsheetImportProvider>
  );
}

export type SpreadsheetImportDialogProps<TKey extends string> = SpreadsheetImportProps<TKey> & {
  open: boolean;
  onOpenChange: (open: boolean) => void;
};

/**
 * The flow in a shadcn Dialog — closest to how upstream shipped it, and what
 * most apps want: a button somewhere that opens an importer over the page.
 */
export function SpreadsheetImportDialog<TKey extends string>({
  open,
  onOpenChange,
  accept,
  className,
  ...options
}: SpreadsheetImportDialogProps<TKey>) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className={className}>
        <DialogHeader className="sr-only">
          <DialogTitle>Import data</DialogTitle>
          <DialogDescription>Upload a spreadsheet and map its columns.</DialogDescription>
        </DialogHeader>
        <SpreadsheetImportProvider options={options}>
          <Flow<TKey> {...(accept ? { accept } : {})} onDone={() => onOpenChange(false)} />
        </SpreadsheetImportProvider>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
